const raw = $input.first().json;

const baseUrl = String(raw.api_base_url || 'http://api:8000').replace(/\/$/, '');
const integrationId = Number(raw.integration_id || 1);
const sessionId = String(raw.sessionId || raw.session_id || 'default-session');
const chatInput = String(raw.chatInput || raw.question || 'Hola');
const email = String(raw.email || 'agent@example.com');
const password = String(raw.password || 'AgentSecret123!');
const bearerToken = String(raw.bearer_token || raw.access_token || '');

return [{
  json: {
    api_base_url: baseUrl,
    integration_id: integrationId,
    session_id: sessionId,
    chatInput: chatInput,
    email: email,
    password: password,
    bearer_token: bearerToken
  }
}];

const ctx = $('Set Session Context1').first().json;
const agentOut = $input.first().json;
return [{
  json: {
    session_id: ctx.session_id,
    question: ctx.chatInput,
    output: agentOut.output || agentOut.text || ''
  }
}];

const req = $('Prepare Chat Context').first().json;
const auth = $input.first().json;
const token = req.bearer_token || auth?.data?.access_token || auth?.access_token || '';
if (!token) {
  throw new Error('Authentication failed: no access_token returned by /api/v1/auth/sessions.');
}
return [{
  json: {
    ...req,
    access_token: token
  }
}];
